import{_ as s,o as t,c as d,a3 as a}from"./chunks/framework.qCVWde4n.js";const k=JSON.parse('{"title":"架构","description":"","frontmatter":{},"headers":[],"relativePath":"zh/architecture.md","filePath":"zh/architecture.md"}'),o={name:"zh/architecture.md"};function i(c,e,n,p,l,r){return t(),d("div",null,[...e[0]||(e[0]=[a(`<h1 id="架构" tabindex="-1">架构 <a class="header-anchor" href="#架构" aria-label="Permalink to &quot;架构&quot;">​</a></h1><p>本文说明各项行为对应哪些源码文件。修改智能体循环、添加工具或调整哨兵（Sentinel）相关行为前，请先阅读。</p><blockquote><p>术语说明：LLM 是生成回答并提出工具调用的大语言模型；运行时是执行智能体和工具的程序；上下文是一次调用模型时提供的指令、对话与工具结果；审批是由用户确认是否允许操作。</p></blockquote><h2 id="one-turn" tabindex="-1">一轮任务的流程 <a class="header-anchor" href="#one-turn" aria-label="Permalink to &quot;一轮任务的流程 {#one-turn}&quot;">​</a></h2><div class="language-mermaid vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">mermaid</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">sequenceDiagram</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    participant U as You (app / terminal)</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    participant A as MuseAgent</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    participant L as LLM</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    participant S as Sentinel</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    participant T as Tool</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    U-&gt;&gt;A: message</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    loop until terminate or max_steps</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">        A-&gt;&gt;L: system prompt + context + tool schemas</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">        L--&gt;&gt;A: text and/or tool calls</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">        A-&gt;&gt;S: guard(call)</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">        S-&gt;&gt;S: policy → allow / ask / deny</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">        S--&gt;&gt;U: approval card (if ask)</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">        U--&gt;&gt;S: decision</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">        S-&gt;&gt;T: execute (vault placeholders resolved)</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">        T--&gt;&gt;S: result</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">        S--&gt;&gt;A: redacted result (+ taint bookkeeping, audit)</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    end</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    A--&gt;&gt;U: final summary</span></span></code></pre></div><p><code>MuseAgent.run()</code> 在每轮开始时组装一次系统提示词，包括配置档案、语言规则、相关记忆和进行中的目标。随后反复调用模型，将模型提出的每个工具调用交给 <code>Sentinel.guard()</code> 检查，并把结果追加到对话中。模型调用 <code>terminate</code>，或直接给出不带工具调用的回答时，本轮结束。App 在任务执行期间发来的新消息，会在下一次模型调用前加入上下文。如果同一调用反复出现却没有进展，系统会触发停滞检测；达到 <code>max_steps</code> 后则强制收尾。</p><h2 id="source-map" tabindex="-1">源码与职责 <a class="header-anchor" href="#source-map" aria-label="Permalink to &quot;源码与职责 {#source-map}&quot;">​</a></h2><table tabindex="0"><thead><tr><th>区域</th><th>文件</th><th>说明</th></tr></thead><tbody><tr><td>公开来源跟进</td><td><code>nanomuse/server/watch_discovery.py</code>、<code>public_watches.py</code>、<code>public_sources.py</code>、<code>public_feed.py</code></td><td>本地发现关注对象，按账号保存选择，匿名读取公开来源并识别变化。网页端把新证据交给 <code>context_watch.py</code>；桌面动态通过短时运行的 <code>watch-stdio</code> 进程复用同一套读取和状态处理逻辑。Android 和 iPhone 打包同一份 <code>android/src/shared/public-watches</code> 规则与来源适配器，通过 Go 读取器连接已校验的公网地址。各端自行处理账号、调度、模型判断和聊天投递。</td></tr><tr><td>组件组装入口</td><td><code>nanomuse/app.py</code></td><td><code>NanoMuseApp</code> 根据设置组装 LLM、工具、保险库、哨兵、记忆、目标和智能体</td></tr><tr><td>智能体循环</td><td><code>nanomuse/agent/core.py</code></td><td>组装提示词、裁剪上下文、检测停滞、持久保存会话、接收中途消息；可选共享<a href="./runtime-budgets">任务预算</a>，缩短工具结果时记录日志</td></tr><tr><td>提示词</td><td><code>nanomuse/prompts.py</code></td><td>系统提示词、语言规则、文字系统检测，以及推进目标的提示词</td></tr><tr><td>哨兵</td><td><code>nanomuse/sentinel/gate.py</code>、<code>policy.py</code>、<code>audit.py</code>、<code>review.py</code></td><td>工具调用检查、决策顺序、审批、污染状态、保险库占位符解析、脱敏和 JSONL 审计日志；可选的后台模型观察不改变执行权限</td></tr><tr><td>保险库</td><td><code>nanomuse/vault/vault.py</code></td><td>Fernet 加密存储，以及 <code>{{vault:NAME}}</code> 机密占位符</td></tr><tr><td>工具基类</td><td><code>nanomuse/tools/base.py</code></td><td><code>BaseTool</code>、<code>CallAssessment</code>、<code>ToolCollection</code>、<code>safe_execute</code></td></tr><tr><td>内置工具</td><td><code>nanomuse/tools/files.py</code>、<code>shell.py</code>、<code>web.py</code>、<code>email_tool.py</code>、<code>browser.py</code> + <code>browser_backends.py</code>，支持服务器 Playwright 或手机 WebView，见 <a href="./browser">browser.md</a>；<code>memory_tools.py</code>、<code>goal_tools.py</code>、<code>terminate.py</code></td><td></td></tr><tr><td>MCP 工具协议</td><td><code>nanomuse/tools/mcp_tools.py</code></td><td>提供 stdio、streamable HTTP 和 SSE 客户端，分别通过标准输入输出、可流式 HTTP 和服务器事件推送通信；每个远程工具对应一个 <code>MCPTool</code>；<code>MCPServerSettings.tools</code> 可覆盖单个工具风险配置</td></tr><tr><td>手机上的运行环境</td><td><code>nanomuse/runtime.py</code>、<code>nanomuse/bridge/</code></td><td><code>device()</code> 读取 <code>NANOMUSE_DEVICE*</code>；<code>DEVICE_TOOLS</code> 定义手机工具的哨兵默认规则；<code>device_mcp_server()</code> 将 App MCP 服务器注册为 <code>device</code>，工具名为 <code>device__*</code>；<code>/api/bridge/*</code> 提供每条命令单独授权的令牌，支持 <code>nanomuse-device</code> / <code>nanomuse-browser</code> / <code>nanomuse-open</code> 命令行桥接，见 <a href="./device">device.md</a>、<a href="./local-runtime">local-runtime.md</a></td></tr><tr><td>手机屏幕操作</td><td><code>nanomuse/phone/link.py</code>、<code>screen.py</code>、<code>operator.py</code>、<code>trace.py</code>、<code>nanomuse/tools/phone.py</code></td><td>管理连接设备，通过 App WebSocket 双向连接收发请求；以截图加说明表示屏幕；操作器使用独立模型运行循环，采用 MemGUI <code>mobile_use</code> 格式、999 网格坐标；生成 JSONL 轨迹及 HTML 查看页面；实现 <code>phone_screen</code> / <code>phone_act</code> / <code>phone_task</code> 及其哨兵评估，见 <a href="./gui">gui.md</a></td></tr><tr><td>LLM</td><td><code>nanomuse/llm/base.py</code>、<code>openai_chat.py</code>、<code>openai_responses.py</code>、<code>prompt_tools.py</code>、<code>factory.py</code>、<code>mock.py</code>；<code>catalogue.py</code> + <code>providers.json</code>、<code>chatgpt.py</code>、<code>codex.py</code>、<code>chatgpt_proxy.py</code></td><td><code>BaseLLM</code> 接口、过滤 <code>&lt;think&gt;</code> 的流式输出、重试、基于提示词的工具调用、测试用 <code>MockLLM</code>；服务商目录记录对话、视觉、图像和视频能力；ChatGPT 登录使用 PKCE 授权校验和令牌存储；<code>provider = &quot;chatgpt&quot;</code> 与 <code>nanomuse chatgpt proxy</code> 负责 Chat Completions ↔ Codex Responses 转换</td></tr><tr><td>记忆与目标</td><td><code>nanomuse/memory/store.py</code>、<code>nanomuse/memory/consolidate.py</code>、<code>nanomuse/goals/store.py</code></td><td>使用 SQLite；关键词和语义检索查询全部存储，不受列表接口默认 1,000 行限制；数据库变更前复用关键词索引，包括编辑、遗忘、恢复及其他连接写入造成的变更；注入记忆时按 IDF，即罕见词权重排序，支持各类字母文字，并将中日韩文本拆为相邻双字；整理计划及检查会拒绝无法判断的合并；变更日志支持撤销</td></tr><tr><td>App 服务器</td><td><code>nanomuse/server/service.py</code>、<code>outbox.py</code>、<code>api.py</code>、<code>webui.py</code>、<code>events.py</code></td><td>对话线程和工作任务管理；持久保存定时任务交接，保证至少交付一次；REST 请求接口和 WebSocket 双向连接；将回调转换为事件的 <code>UI</code> 实现；持久保存时间线</td></tr><tr><td>前端</td><td><code>web/src/</code></td><td>React + TypeScript + Tailwind；<code>store.tsx</code> 管理状态及 WebSocket，<code>screens/</code> 实现标签页，<code>components/</code> 提供卡片、形象和 Markdown 组件</td></tr><tr><td>终端</td><td><code>nanomuse/console.py</code>、<code>nanomuse/cli.py</code></td><td>使用 Rich 构建控制台界面并在其中处理审批；使用 Typer 提供命令</td></tr><tr><td>配置与数据结构</td><td><code>nanomuse/config.py</code>、<code>nanomuse/schema.py</code></td><td>Pydantic 设置，以及消息和工具调用的数据模型</td></tr></tbody></table><p>发送 Responses API 请求前，Python 运行时的 <code>openai_responses</code>、<code>codex.py</code> 中的 Codex Responses 转换，以及 Android、iOS 的序列化器，都会保证本次请求中的 <code>function_call.call_id</code> 唯一，并对配对的 <code>function_call_output</code> 使用相同的新 ID。序列化器负责把程序对象转换为请求数据。这种改写只作用于本次请求，推理条目的 ID 保持不变。</p><h2 id="the-ui-protocol" tabindex="-1"><code>UI</code> 协议 <a class="header-anchor" href="#the-ui-protocol" aria-label="Permalink to &quot;\`UI\` 协议 {#the-ui-protocol}&quot;">​</a></h2><p>任何向用户展示智能体的界面，都需要实现 <code>nanomuse/ui.py::UI</code>。协议包括增量文字、助手消息、工具调用及结果、哨兵通知、<code>ask_approval()</code> 和 <code>ask_user()</code>。<code>ConsoleUI</code> 是终端实现；<code>WebUI</code> 将同样的回调转为时间线事件和 WebSocket 消息，并用 future（等待异步结果的对象）暂存审批，直到 App 回答。Telegram 或其他桌面前端也可以实现该协议，或直接作为 HTTP API 客户端连接。</p><h2 id="threads-in-the-app" tabindex="-1">App 中的对话线程 <a class="header-anchor" href="#threads-in-the-app" aria-label="Permalink to &quot;App 中的对话线程 {#threads-in-the-app}&quot;">​</a></h2><p><code>MuseService</code> 为每个对话线程保留一个 <code>MuseAgent</code>。每个线程有独立对话和后台执行任务，共享记忆库、目标库、保险库和审计日志。主线程对应长期使用的「主要聊天」，旁聊各自使用独立线程；后台目标检查也在单独线程运行，再向主要聊天发送摘要。<code>contextvar</code> 用于告诉 <code>WebUI</code> 当前回调属于哪个线程。</p><p>时间线写入会合并处理，并通过版本号区分先后。关闭时会写入最新快照，较早工作任务的写入不能在之后覆盖它。模型对话历史先写到目标旁的临时文件，再通过原子替换更新，也就是整份文件一次替换；如果写入失败，之前有效的 JSON 文件仍然保留。</p><h2 id="extension-points" tabindex="-1">扩展方式 <a class="header-anchor" href="#extension-points" aria-label="Permalink to &quot;扩展方式 {#extension-points}&quot;">​</a></h2><table tabindex="0"><thead><tr><th>要添加什么</th><th>实现方式</th></tr></thead><tbody><tr><td>工具</td><td>在 <code>nanomuse/tools/</code> 继承 <code>BaseTool</code>，声明 <code>risk</code>；某些调用比默认风险高时重写 <code>assess()</code>；在 <code>app.py::_build_tools</code> 注册，并添加使用 <code>MockLLM</code> 的测试</td></tr><tr><td>连接器</td><td>优先使用 MCP 服务器，即 <code>[[mcp.servers]]</code>；协议不适合时再编写工具</td></tr><tr><td>模型服务商</td><td>多数接口可直接使用 <code>openai</code> / <code>openai_responses</code>；否则实现 <code>BaseLLM</code>，并在 <code>llm/factory.py</code> 中注册</td></tr><tr><td>前端</td><td>实现 <code>UI</code>，或按照 <code>docs/app.md</code> 调用 HTTP/WebSocket API</td></tr><tr><td>哨兵行为</td><td>决策逻辑修改 <code>policy.py</code>，执行前后的处理修改 <code>gate.py</code></td></tr></tbody></table><h2 id="tests" tabindex="-1">测试 <a class="header-anchor" href="#tests" aria-label="Permalink to &quot;测试 {#tests}&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">python</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -m</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> pytest</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -q</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">                 # unit tests with MockLLM, no network</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">NANOMUSE_LIVE</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">1</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> python</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -m</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> pytest</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -q</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -m</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> live</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">    # smoke test against your configured model</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">ruff</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> check</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> nanomuse</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> tests</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> &amp;&amp; </span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">ruff</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> format</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --check</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> nanomuse</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> tests</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> web</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> &amp;&amp; </span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> build</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">             # type-checks and rebuilds the app</span></span></code></pre></div><p><code>tests/test_server.py</code> 使用预设响应的 <code>MockLLM</code> 对 App 服务器进行端到端测试，覆盖发消息、审批卡片、提问、目标、记忆、文件和设置。</p><p><a href="./gui-regression">GUI 回归</a>说明固定模拟任务、独立状态检查，以及参考实现和真实模型的测试入口。它的用量记录功能不要求启用任务预算。</p><p><a href="./goal-eval">目标评测任务</a>介绍十条已录制任务轨迹，以及需主动启用的模型测试。</p>`,21)])])}const y=s(o,[["render",i]]);export{k as __pageData,y as default};
